"use client";

import React, { useState } from "react";
import { X } from "lucide-react";
import styles from "../academic.module.css";
import { Department } from "./DepartmentTable";

interface CreateProgramDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  departments: Department[];
  onSubmit: (programName: string, department: string, degreeLevel: string, duration: string) => void;
}

export default function CreateProgramDrawer({ isOpen, onClose, departments, onSubmit }: CreateProgramDrawerProps) {
  const [programName, setProgramName] = useState("");
  const [department, setDepartment] = useState("");
  const [degreeLevel, setDegreeLevel] = useState("");
  const [duration, setDuration] = useState("");
  const [intake, setIntake] = useState("");
  const [description, setDescription] = useState("");

  if (!isOpen) return null;

  const isFormValid = programName.trim() && department && degreeLevel && duration;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!isFormValid) return;

    onSubmit(programName.trim(), department, degreeLevel, duration);

    // Reset form
    setProgramName("");
    setDepartment("");
    setDegreeLevel("");
    setDuration("");
    setIntake("");
    setDescription("");
  };

  return (
    <div className={styles.drawerOverlay}>
      <div className={styles.drawerContainer}>
        <div className={styles.drawerHeader}>
          <div className={styles.drawerTitleArea}>
            <h2 className={styles.drawerTitle}>Create Academic Program</h2>
            <p className={styles.drawerSubtitle}>Add a new academic program under an existing department.</p>
          </div>
          <button className={styles.drawerCloseBtn} onClick={onClose} aria-label="Close">
            <X size={20} />
          </button>
        </div>

        <div className={styles.drawerBody}>
          <div className={styles.drawerFormGroup}>
            <label className={styles.drawerLabel}>
              Program Name <span>*</span>
            </label>
            <input 
              type="text" 
              className={styles.drawerInput} 
              placeholder="Enter program name (e.g. B.Tech Computer Science)" 
              value={programName}
              onChange={(e) => setProgramName(e.target.value)}
              autoFocus
            />
          </div>

          <div className={styles.drawerFormGroup}>
            <label className={styles.drawerLabel}>
              Department <span>*</span>
            </label>
            <select 
              className={styles.drawerSelect}
              value={department}
              onChange={(e) => setDepartment(e.target.value)}
            >
              <option value="">Select Department</option>
              {departments.map((dept) => (
                <option key={dept.id} value={dept.name}>{dept.name}</option>
              ))}
            </select>
          </div>

          <div className={styles.drawerFormGroup}>
            <label className={styles.drawerLabel}>
              Degree Level <span>*</span>
            </label>
            <select 
              className={styles.drawerSelect}
              value={degreeLevel}
              onChange={(e) => setDegreeLevel(e.target.value)}
            >
              <option value="">Select Degree Level</option>
              <option value="Bachelor's">Bachelor's</option>
              <option value="Master's">Master's</option>
              <option value="Diploma">Diploma</option>
              <option value="Doctorate">Doctorate</option>
            </select>
          </div>

          <div className={styles.drawerFormGroup}>
            <label className={styles.drawerLabel}>
              Duration <span>*</span>
            </label>
            <select 
              className={styles.drawerSelect}
              value={duration}
              onChange={(e) => setDuration(e.target.value)}
            >
              <option value="">Select Duration</option>
              <option value="1 Year">1 Year</option>
              <option value="2 Years">2 Years</option>
              <option value="3 Years">3 Years</option>
              <option value="4 Years">4 Years</option>
              <option value="5 Years">5 Years</option>
              <option value="6 Years">6 Years</option>
            </select>
          </div>

          <div className={styles.drawerFormGroup}>
            <label className={styles.drawerLabel}>Intake Capacity (Optional)</label>
            <input 
              type="number" 
              className={styles.drawerInput} 
              placeholder="Example: 240" 
              value={intake}
              onChange={(e) => setIntake(e.target.value)}
            />
            <span style={{ fontSize: '12px', color: 'var(--text-muted)' }}>
              Maximum number of students that can enroll in this program.
            </span>
          </div>

          <div className={styles.drawerFormGroup}>
            <label className={styles.drawerLabel}>Description (Optional)</label>
            <textarea 
              className={styles.drawerTextarea} 
              placeholder="Provide a brief description of this academic program."
              rows={4}
              style={{ resize: "none" }}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
          </div>
        </div>

        <div className={styles.drawerFooter}>
          <button className={styles.drawerBtnCancel} onClick={onClose}>
            Cancel
          </button>
          <button 
            className={styles.drawerBtnCreate} 
            onClick={handleSubmit}
            disabled={!isFormValid}
          >
            Create Program
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";

import { Plus } from "lucide-react";
import styles from "../academic.module.css";
import Link from "next/link";

interface PageHeaderProps {
  activeTab: string;
  onCreateClick?: () => void;
}

export default function PageHeader({ activeTab, onCreateClick }: PageHeaderProps) {
  const isDepartments = activeTab === "departments";

  return (
    <div>
      <div className={styles.headerRow}>
        <div>
          <h1 className={styles.title}>{isDepartments ? "Departments" : "Academics"}</h1>
          <p className={styles.subtitle}>
            {isDepartments 
              ? "Manage your institution's academic structure and departmental hierarchy."
              : "Manage your institution's academic structure, including departments and academic programs."}
          </p>
        </div>

        <button className={styles.primaryButton} onClick={onCreateClick}>
          <Plus size={16} />
          {isDepartments ? "Create Department" : "Create Program"}
        </button>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useRef, useEffect } from "react";
import styles from "../admin-layout.module.css";
import { usePathname } from "next/navigation";
import { User, LogOut } from "lucide-react";
import Link from "next/link";

export default function Header() {
  const pathname = usePathname();
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const getHeaderTitle = () => {
    if (pathname.includes("/admin/academic-structure")) return "Academics";
    if (pathname.includes("/admin/user-management")) return "Directory";
    if (pathname.includes("/admin/settings")) return "Settings";
    if (pathname.includes("/admin/reports")) return "Reports & Analytics";
    return "Dashboard"; 
  };

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  return (
    <header className={styles.header}>
      <h1 className={styles.headerTitle} style={{ color: "var(--text-main)" }}>{getHeaderTitle()}</h1>

      <div className={styles.headerActions}>
        <div ref={dropdownRef} style={{ position: "relative" }}>
          <button suppressHydrationWarning 
            onClick={() => setIsDropdownOpen(!isDropdownOpen)}
            style={{
              background: "none",
              border: "none",
              cursor: "pointer",
              padding: 0,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              borderRadius: "50%",
              overflow: "hidden"
            }}
          >
            <img 
              src="https://api.dicebear.com/7.x/initials/svg?seed=Nitya%20Nara&backgroundColor=e2e8f0&textColor=475569" 
              alt="Profile" 
              style={{
                width: "32px",
                height: "32px",
                objectFit: "cover"
              }}
            />
          </button>

          {isDropdownOpen && (
            <div style={{
              position: "absolute",
              top: "100%",
              right: 0,
              marginTop: "8px",
              width: "250px",
              backgroundColor: "white",
              borderRadius: "12px",
              boxShadow: "0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05)",
              border: "1px solid #e2e8f0",
              zIndex: 50,
              overflow: "hidden"
            }}>
              <div style={{ padding: "16px", display: "flex", alignItems: "center", gap: "12px", borderBottom: "1px solid #e2e8f0" }}>
                <img 
                  src="https://api.dicebear.com/7.x/initials/svg?seed=Nitya%20Nara&backgroundColor=e2e8f0&textColor=475569" 
                  alt="Nitya Nara" 
                  style={{ width: "42px", height: "42px", borderRadius: "50%" }}
                />
                <div style={{ display: "flex", flexDirection: "column" }}>
                  <span style={{ fontSize: "15px", fontWeight: 600, color: "#0f172a" }}>Nitya Nara</span>
                  <span style={{ fontSize: "13px", color: "#64748b" }}>nitya_nara@srmap.edu.in</span>
                </div>
              </div>

              <div style={{ padding: "8px" }}>
                <Link 
                  href="/admin/profile" 
                  onClick={() => setIsDropdownOpen(false)} 
                  style={{
                    width: "100%",
                    display: "flex",
                    alignItems: "center",
                    gap: "12px",
                    padding: "10px 12px",
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    fontSize: "15px",
                    color: "#334155",
                    borderRadius: "8px",
                    textAlign: "left",
                    fontWeight: 500,
                    textDecoration: "none",
                    boxSizing: "border-box"
                  }}
                  onMouseOver={(e) => e.currentTarget.style.backgroundColor = "#f8fafc"}
                  onMouseOut={(e) => e.currentTarget.style.backgroundColor = "transparent"}
                >
                  <User size={18} style={{ color: "#64748b" }} />
                  Account
                </Link>
              </div>

              <div style={{ borderTop: "1px solid #e2e8f0", padding: "8px" }}>
                <button suppressHydrationWarning style={{
                  width: "100%",
                  display: "flex",
                  alignItems: "center",
                  gap: "12px",
                  padding: "10px 12px",
                  background: "none",
                  border: "none",
                  cursor: "pointer",
                  fontSize: "15px",
                  color: "#334155",
                  borderRadius: "8px",
                  textAlign: "left",
                  fontWeight: 500
                }}
                onMouseOver={(e) => e.currentTarget.style.backgroundColor = "#f8fafc"}
                onMouseOut={(e) => e.currentTarget.style.backgroundColor = "transparent"}
                >
                  <LogOut size={18} style={{ color: "#64748b" }} />
                  Log out
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </header>
  );
}

