"use client";

import React from 'react';
import { usePathname } from 'next/navigation';
import { Bell, HelpCircle } from 'lucide-react';

export default function Header() {
  const pathname = usePathname() || '';

  // Determine breadcrumb based on route
  let activePageName = 'Faculty Dashboard';

  if (pathname.startsWith('/faculty/subjects')) {
    activePageName = 'Subjects';
  } else if (pathname.startsWith('/faculty/pulse-sessions')) {
    activePageName = 'Pulse Sessions';
  } else if (pathname.startsWith('/faculty/live-sessions')) {
    activePageName = 'Live Sessions';
  } else if (pathname.startsWith('/faculty/session-summary')) {
    activePageName = 'Session Summary';
  } else if (pathname.startsWith('/faculty/concept-gap-analysis')) {
    activePageName = 'Concept Gap Analysis';
  } else if (pathname.startsWith('/faculty/reports')) {
    activePageName = 'Reports';
  } else if (pathname.startsWith('/faculty/profile')) {
    activePageName = 'Profile';
  } else if (pathname.startsWith('/faculty/help')) {
    activePageName = 'Help Center';
  }

  return (
    <header className="top-header">
      <div className="breadcrumbs">
        <span>Dashboard</span>
        <span className="breadcrumb-separator">{'>'}</span>
        <span>Faculty</span>
        <span className="breadcrumb-separator">{'>'}</span>
        <span className="breadcrumb-active">{activePageName}</span>
      </div>

      <div className="header-actions">
        <button className="icon-btn">
          <Bell size={20} />
        </button>
        <button className="icon-btn">
          <HelpCircle size={20} />
        </button>

        <div className="user-profile">
          <div className="user-info">
            <span className="user-name">Dr. Aris V. K.</span>
            <span className="user-role">Senior Faculty, CSE</span>
          </div>
          <img 
            src="https://api.dicebear.com/7.x/avataaars/svg?seed=Felix&backgroundColor=e2e8f0" 
            alt="Profile Avatar" 
            className="avatar" 
          />
        </div>
      </div>
    </header>
  );
}

"use client";

import React from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { 
  LayoutDashboard, 
  BookOpen, 
  Activity, 
  Radio, 
  BarChart2, 
  Target, 
  FileText, 
  User, 
  HelpCircle, 
  LogOut
} from 'lucide-react';

export default function Sidebar() {
  const pathname = usePathname() || '';

  const navItems = [
    { name: 'Dashboard', path: '/faculty/dashboard', icon: LayoutDashboard },
    { name: 'Subjects', path: '/faculty/subjects', icon: BookOpen },
    { name: 'Pulse Sessions', path: '/faculty/pulse-sessions', icon: Activity },

    { name: 'Concept Gap Analysis', path: '/faculty/concept-gap-analysis', icon: Target },
    { name: 'Reports', path: '/faculty/reports', icon: FileText },
  ];

  const bottomNavItems = [
    { name: 'Profile', path: '/faculty/profile', icon: User },
    { name: 'Help Center', path: '/faculty/help', icon: HelpCircle },
  ];

  return (
    <aside className="sidebar">
      <div className="sidebar-header">
        <div className="sidebar-brand">
          MyStory CIP
          <span className="sidebar-subtitle">Academic Intelligence</span>
        </div>
      </div>

      <nav className="sidebar-nav">
        {navItems.map((item) => {
          const Icon = item.icon;
          // Dashboard needs exact match so it doesn't highlight when on /faculty/dashboard-something-else (not that we have any, but good practice)
          const isActive = item.path === '/faculty/dashboard' 
            ? pathname === item.path 
            : pathname.startsWith(item.path);

          return (
            <Link key={item.name} href={item.path} className={`sidebar-nav-item ${isActive ? 'active' : ''}`}>
              <Icon className="sidebar-icon" /> {item.name}
            </Link>
          );
        })}

        <div className="sidebar-divider"></div>

        {bottomNavItems.map((item) => {
          const Icon = item.icon;
          const isActive = pathname.startsWith(item.path);
          return (
            <Link key={item.name} href={item.path} className={`sidebar-nav-item ${isActive ? 'active' : ''}`}>
              <Icon className="sidebar-icon" /> {item.name}
            </Link>
          );
        })}
        <Link href="/logout" className="sidebar-nav-item">
          <LogOut className="sidebar-icon" /> Sign Out
        </Link>
      </nav>
    </aside>
  );
}

"use client";
import { apiClient } from '@/lib/apiClient';


import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import { 
  Info,
  Download,
  Calendar,
  AlertCircle,
  TrendingUp,
  BrainCircuit,
  ArrowLeft,
  Users
} from 'lucide-react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell,
  PieChart, Pie,
  LineChart, Line, Legend
} from 'recharts';
import styles from './concept-gap-analysis.module.css';

export default function ConceptGapAnalysisPage() {
  const [dashboardData, setDashboardData] = useState<unknown>(null);
  const [trendData, setTrendData] = useState<unknown>(null);
  const [insightsData, setInsightsData] = useState<unknown>(null);
  const [loading, setLoading] = useState(true);

  // Filters
  const [subjectId, setSubjectId] = useState('');

  const fetchAnalytics = async () => {
    setLoading(true);
    try {
      const queryParams = new URLSearchParams();
      if (subjectId) queryParams.append('courseId', subjectId);

      const qs = queryParams.toString();

      const [dashRes, trendRes, insRes] = await Promise.all([
        apiClient.get(`/api/faculty/analytics/concept-gap?${qs}`),
        apiClient.get(`/api/faculty/analytics/concept-gap/trend?${qs}`),
        apiClient.get(`/api/faculty/analytics/concept-gap/insights?${qs}`)
      ]);

      if (dashRes.ok && trendRes.ok && insRes.ok) {
        const dashJson = dashRes;
        const trendJson = trendRes;
        const insJson = insRes;

        setDashboardData(dashJson.data);
        setTrendData(trendJson.data);
        setInsightsData(insJson.data);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAnalytics();
  }, [subjectId]);

  const handleExportCSV = async () => {
    try {
      const queryParams = new URLSearchParams();
      if (subjectId) queryParams.append('courseId', subjectId);
      const url = `/api/faculty/analytics/concept-gap/export?${queryParams.toString()}`;
      window.open(url, '_blank');
    } catch (err) {
      console.error('Failed to export CSV', err);
    }
  };

  const getRingColor = (pct: number) => {
    if (pct >= 70) return '#16A34A';
    if (pct >= 50) return '#F59E0B';
    return '#EF4444';
  };

  // Build line chart data
  // We need a uniform dataset where each object represents a date, and keys are concept names
  const lineChartData: unknown[] = [];
  if (trendData?.trends) {
    const dateSet = new Set<string>();
    trendData.trends.forEach((t: unknown) => t.dataPoints.forEach((dp: unknown) => dateSet.add(dp.date)));

    Array.from(dateSet).sort().forEach(date => {
      const obj: unknown = { date };
      trendData.trends.forEach((t: unknown) => {
        const dp = t.dataPoints.find((d: unknown) => d.date === date);
        if (dp) obj[t.conceptName] = dp.masteryPercentage;
      });
      lineChartData.push(obj);
    });
  }

  const lineColors = ['#16A34A', '#3B82F6', '#F59E0B', '#EF4444', '#8B5CF6', '#14B8A6'];

  return (
    <div className={`dashboard-scroll ${styles.container}`}>
      {/* Header & Filters */}
      <div className={styles.headerRow}>
        <div className={styles.titleSection}>
          <h1>Concept Gap Analysis</h1>
          <p>Identify learning gaps and track concept-wise performance.</p>
        </div>
        <div className={styles.filterSection}>
          <select 
            className={styles.filterInput}
            value={subjectId}
            onChange={(e) => setSubjectId(e.target.value)}
          >
            <option value="">All Subjects</option>
            {/* Real subjects could be fetched and mapped here */}
          </select>
          <button className={styles.applyButton} onClick={fetchAnalytics}>
            Apply Filters
          </button>
        </div>
      </div>

      {loading ? (
        <div style={{ display: 'flex', justifyContent: 'center', padding: '100px' }}>
          <div style={{ width: '40px', height: '40px', borderRadius: '50%', border: '3px solid #E7E3DB', borderTopColor: '#10633B', animation: 'spin 1s linear infinite' }} />
          <style dangerouslySetInnerHTML={{__html: `@keyframes spin { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }`}} />
        </div>
      ) : !dashboardData ? (
        <div style={{ padding: '40px', textAlign: 'center', background: '#fff', borderRadius: '12px' }}>
          <AlertCircle size={48} color="#D97706" style={{ margin: '0 auto 16px' }} />
          <h3>No Data Available</h3>
          <p>Complete at least one pulse session to view analytics.</p>
        </div>
      ) : (
        <>
          {/* Row 1: KPIs */}
          <div className={styles.kpiGrid}>
            <div className={styles.kpiCard}>
              <div className={styles.kpiInfo}>
                <div className={styles.kpiTitle}>Overall Class Mastery <Info size={14} color="#98A2B3" /></div>
                <div className={styles.kpiValue}>{dashboardData.overallClassMastery}%</div>
                <div className={styles.kpiSubtitle}>Average Mastery</div>
              </div>
              <div className={styles.kpiRingContainer}>
                <svg width="60" height="60" viewBox="0 0 60 60">
                  <circle cx="30" cy="30" r="26" fill="none" stroke="#E7E3DB" strokeWidth="6" />
                  <circle 
                    cx="30" cy="30" r="26" fill="none" stroke={getRingColor(dashboardData.overallClassMastery)} strokeWidth="6"
                    strokeDasharray={`${(dashboardData.overallClassMastery / 100) * 163.36} 163.36`}
                    transform="rotate(-90 30 30)"
                    strokeLinecap="round"
                  />
                </svg>
                <span className={styles.kpiRingText}>{dashboardData.overallClassMastery}%</span>
              </div>
            </div>

            <div className={styles.kpiCard}>
              <div className={styles.kpiInfo}>
                <div className={styles.kpiTitle}>Strong Concepts <Info size={14} color="#98A2B3" /></div>
                <div className={styles.kpiValue}>{dashboardData.strongConceptsCount}</div>
                <div className={styles.kpiSubtitle}>Concepts</div>
              </div>
              <div className={styles.kpiRingContainer}>
                <svg width="60" height="60" viewBox="0 0 60 60">
                  <circle cx="30" cy="30" r="26" fill="none" stroke="#E7E3DB" strokeWidth="6" />
                  <circle 
                    cx="30" cy="30" r="26" fill="none" stroke="#16A34A" strokeWidth="6"
                    strokeDasharray={`${(dashboardData.strongConceptsCount / Math.max(1, dashboardData.conceptMasteryOverview.length)) * 163.36} 163.36`}
                    transform="rotate(-90 30 30)"
                    strokeLinecap="round"
                  />
                </svg>
              </div>
            </div>

            <div className={styles.kpiCard}>
              <div className={styles.kpiInfo}>
                <div className={styles.kpiTitle}>Needs Improvement <Info size={14} color="#98A2B3" /></div>
                <div className={styles.kpiValue}>{dashboardData.needsImprovementCount}</div>
                <div className={styles.kpiSubtitle}>Concepts</div>
              </div>
              <div className={styles.kpiRingContainer}>
                <svg width="60" height="60" viewBox="0 0 60 60">
                  <circle cx="30" cy="30" r="26" fill="none" stroke="#E7E3DB" strokeWidth="6" />
                  <circle 
                    cx="30" cy="30" r="26" fill="none" stroke="#F59E0B" strokeWidth="6"
                    strokeDasharray={`${(dashboardData.needsImprovementCount / Math.max(1, dashboardData.conceptMasteryOverview.length)) * 163.36} 163.36`}
                    transform="rotate(-90 30 30)"
                    strokeLinecap="round"
                  />
                </svg>
              </div>
            </div>

            <div className={styles.kpiCard}>
              <div className={styles.kpiInfo}>
                <div className={styles.kpiTitle}>Critical Gaps <Info size={14} color="#98A2B3" /></div>
