            </table>
          </div>
        </div>

        {/* Right Column */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>

          {/* Analytics Card */}
          <div className={styles.card}>
            <h3 className={styles.cardTitle}>Session Analytics</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <div className={styles.statRow}>
                <span className={styles.statLabel}>Participation Rate</span>
                <span className={styles.statValue}>{kpis.participationPercentage}%</span>
              </div>
              <div className={styles.statRow}>
                <span className={styles.statLabel}>Students Remaining</span>
                <span className={styles.statValue}>{kpis.studentsRemaining}</span>
              </div>
            </div>

            <div style={{ marginTop: '24px' }}>
              <h4 style={{ fontSize: '0.85rem', color: '#667085', margin: '0 0 16px 0', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Question Progress</h4>

              {questionProgress.map((qp: unknown) => {
                const fillPercent = kpis.studentsJoined > 0 ? (qp.totalAnswers / kpis.studentsJoined) * 100 : 0;
                return (
                  <div key={qp.questionId} className={styles.questionItem}>
                    <div className={styles.questionHeader}>
                      <span style={{ fontWeight: 500 }}>Q{qp.questionNumber}</span>
                      <span style={{ color: '#667085' }}>{qp.totalAnswers} answers</span>
                    </div>
                    <div className={styles.progressBarContainer}>
                      <div className={styles.progressBarFill} style={{ width: `${fillPercent}%` }}></div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Join Info */}
          <div className={styles.card}>
            <h3 className={styles.cardTitle}>Join Information</h3>
            <div className={styles.codeBox}>
              <div style={{ fontSize: '0.85rem', color: '#667085', marginBottom: '8px', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Session Code</div>
              <div className={styles.sessionCode}>{session.sessionCode || 'PENDING'}</div>
            </div>

            <div style={{ display: 'flex', gap: '12px', marginTop: '16px' }}>
              <button className="btn btn-secondary" style={{ flex: 1, padding: '8px', display: 'flex', justifyContent: 'center' }}>
                <Copy size={16} />
              </button>
              <button className="btn btn-secondary" style={{ flex: 1, padding: '8px', display: 'flex', justifyContent: 'center' }}>
                <Download size={16} />
              </button>
              <button className="btn btn-secondary" style={{ flex: 1, padding: '8px', display: 'flex', justifyContent: 'center' }}>
                <Share2 size={16} />
              </button>
            </div>
          </div>

        </div>
      </div>

      {/* Sticky Bottom Bar */}
      <div className={styles.stickyActionBar}>
        <div className={styles.actionLeft}>
          <div style={{ display: 'flex', flexDirection: 'column' }}>
            <span style={{ fontSize: '0.75rem', color: '#667085', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Live Since</span>
            <span style={{ fontWeight: 600, color: '#17223B' }}>{new Date(session.timerActualStartTime || session.createdAt).toLocaleTimeString()}</span>
          </div>
          <div style={{ width: '1px', height: '24px', backgroundColor: '#E7E3DB' }}></div>
          <div style={{ display: 'flex', flexDirection: 'column' }}>
            <span style={{ fontSize: '0.75rem', color: '#667085', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Participants</span>
            <span style={{ fontWeight: 600, color: '#17223B' }}>{kpis.studentsJoined} Active</span>
          </div>
        </div>
        <div className={styles.actionRight}>
          <button className="btn btn-secondary" style={{ padding: '10px 24px' }}>
            Pause Session
          </button>
          <button 
            className="btn btn-primary" 
            style={{ padding: '10px 24px', backgroundColor: '#DC2626', borderColor: '#DC2626' }}
            onClick={() => setShowEndDialog(true)}
          >
            End Session
          </button>
        </div>
      </div>

      {/* End Session Confirmation Dialog */}
      {showEndDialog && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.5)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ backgroundColor: '#fff', borderRadius: '12px', padding: '24px', width: '100%', maxWidth: '400px', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}>
            <h3 style={{ margin: '0 0 12px 0', fontSize: '1.25rem', color: '#17223B' }}>End Session?</h3>
            <p style={{ color: '#667085', marginBottom: '24px', lineHeight: '1.5' }}>
              Are you sure you want to end this session? Students will no longer be able to submit answers. This action cannot be undone.
            </p>
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px' }}>
              <button 
                className="btn btn-secondary" 
                onClick={() => setShowEndDialog(false)}
                disabled={ending}
              >
                Cancel
              </button>
              <button 
                className="btn btn-primary" 
                style={{ backgroundColor: '#DC2626', borderColor: '#DC2626' }}
                onClick={handleEndSession}
                disabled={ending}
              >
                {ending ? 'Ending...' : 'End Session'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Global CSS for animation */}
      <style dangerouslySetInnerHTML={{__html: `
        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
        @keyframes pulse {
          0% { opacity: 1; transform: scale(1); }
          50% { opacity: 0.5; transform: scale(1.2); }
          100% { opacity: 1; transform: scale(1); }
        }
      `}} />
    </div>
  );
}

/* eslint-disable @typescript-eslint/no-explicit-any */
"use client";
import { apiClient } from '@/lib/apiClient';


import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import { 
  Users, 
  CheckCircle, 
  Activity, 
  Clock, 
  Download,
  Share2,
  AlertCircle,
  FileText,
  ChevronRight,
  TrendingUp,
  BrainCircuit,
  Eye
} from 'lucide-react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';
import styles from './summary-pulse.module.css';

interface SummaryPageProps {
  params: Promise<{ id: string }>;
}

export default function SessionSummaryPage({ params }: SummaryPageProps) {
  const { id } = React.use(params);

  const [sessionData, setSessionData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchSummaryData = async () => {
      try {
        const res = await apiClient.get(`/api/faculty/pulse-sessions/${id}/summary`);
        if (res.ok) {
          const json = res;
          setSessionData(json.data);
        } else {
          const json = res;
          setError(json.error || 'Failed to load session summary');
        }
      } catch (e) {
        console.error(e);
        setError('Network error while loading summary.');
      } finally {
        setLoading(false);
      }
    };
    fetchSummaryData();
  }, [id]);

  if (loading) {
    return (
      <div className={`dashboard-scroll ${styles.container}`} style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{ width: '40px', height: '40px', borderRadius: '50%', border: '3px solid #E7E3DB', borderTopColor: '#10633B', animation: 'spin 1s linear infinite', margin: '0 auto 16px' }} />
          <p style={{ color: '#667085' }}>Generating Session Summary...</p>
        </div>
        <style dangerouslySetInnerHTML={{__html: `
          @keyframes spin {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(360deg); }
          }
        `}} />
      </div>
    );
  }

  if (error || !sessionData) {
    return (
      <div className={`dashboard-scroll ${styles.container}`} style={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ textAlign: 'center', maxWidth: '400px' }}>
          <AlertCircle size={48} color="#D97706" style={{ margin: '0 auto 16px' }} />
          <h2 style={{ fontSize: '1.25rem', color: '#17223B', margin: '0 0 8px 0' }}>Summary Unavailable</h2>
          <p style={{ color: '#667085', margin: '0 0 24px 0' }}>{error}</p>
          <Link href="/faculty/pulse-sessions" className="btn btn-primary" style={{ textDecoration: 'none' }}>
            Return to Pulse Sessions
          </Link>
        </div>
      </div>
    );
  }

  const { session, kpis, questionProgress, students } = sessionData;

  // Compute Score Distribution for Doughnut Chart
  let needsRemedial = 0; // < 40%
  let reviewTopic = 0;   // 40% - 75%
  let excellent = 0;     // > 75%

  const studentsWithScore = students.filter((s: any) => s.hasAttempted);

  studentsWithScore.forEach((s: any) => {
    const p = s.percentage || 0;
    if (p < 40) needsRemedial++;
    else if (p <= 75) reviewTopic++;
    else excellent++;
  });

  const chartData = [
    { name: 'Needs Remedial (<40%)', value: needsRemedial, color: '#DC2626' },
    { name: 'Review Topic (40-75%)', value: reviewTopic, color: '#D97706' },
    { name: 'Excellent (>75%)', value: excellent, color: '#166534' },
  ].filter(d => d.value > 0);

  // Computed Insights
  let lowestQuestion: any = null;
  let lowestAccuracy = 100;

  questionProgress.forEach((qp: any) => {
    const accuracy = qp.totalAnswers > 0 ? (qp.correctAnswers / qp.totalAnswers) * 100 : 0;
    if (accuracy < lowestAccuracy) {
      lowestAccuracy = accuracy;
      lowestQuestion = qp;
    }
  });

  const durationMin = session.durationMinutes || 0;

  return (
    <div className={`dashboard-scroll ${styles.container}`}>
      {/* Header */}
      <div className="page-header" style={{ marginBottom: '24px' }}>
        <div className="page-title-section">
          <div style={{ fontSize: '0.85rem', color: '#667085', marginBottom: '8px', display: 'flex', alignItems: 'center', gap: '8px' }}>
            <Link href="/faculty" style={{ color: 'inherit', textDecoration: 'none' }}>Faculty</Link> <ChevronRight size={14} /> 
            <Link href="/faculty/pulse-sessions" style={{ color: 'inherit', textDecoration: 'none' }}>Pulse Sessions</Link> <ChevronRight size={14} /> 
            <span style={{ color: '#17223B', fontWeight: 500 }}>Session Summary</span>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <h1 className="page-title" style={{ margin: 0 }}>{session.title}</h1>
            <div className={`${styles.badge} ${styles.blue}`}>COMPLETED</div>
          </div>
          <div className="page-tags" style={{ marginTop: '8px' }}>
            <span style={{ color: '#667085', fontSize: '0.9rem' }}>
              Completed on {new Date(session.createdAt).toLocaleDateString()}
            </span>
          </div>
        </div>
        <div className="page-actions">
          <button className="btn btn-secondary">
            <Download size={18} /> Download Report
          </button>
        </div>
      </div>

      {/* KPI Cards */}
      <div className={styles.kpiGrid}>
        <div className={styles.kpiCard}>
          <div className={`${styles.kpiIcon} ${styles.blue}`}>
            <Activity size={24} />
          </div>
          <div>
            <div className={styles.kpiValue}>{kpis.participationPercentage}%</div>
            <div className={styles.kpiLabel}>Participation</div>
          </div>
        </div>
        <div className={styles.kpiCard}>
          <div className={`${styles.kpiIcon} ${styles.green}`}>
            <CheckCircle size={24} />
          </div>
          <div>
            <div className={styles.kpiValue}>{kpis.responsesSubmitted}</div>
            <div className={styles.kpiLabel}>Participated</div>
          </div>
        </div>
        <div className={styles.kpiCard}>
          <div className={`${styles.kpiIcon} ${styles.teal}`}>
            <Activity size={24} />
          </div>
          <div>
            <div className={styles.kpiValue}>{kpis.participationPercentage}%</div>
            <div className={styles.kpiLabel}>Participation Rate</div>
          </div>
        </div>
        <div className={styles.kpiCard}>
          <div className={`${styles.kpiIcon} ${styles.purple}`}>
            <TrendingUp size={24} />
          </div>
          <div>
            <div className={styles.kpiValue}>{kpis.averageScore}%</div>
            <div className={styles.kpiLabel}>Average Score</div>
          </div>
        </div>
        <div className={styles.kpiCard}>
          <div className={`${styles.kpiIcon} ${styles.orange}`}>
            <Clock size={24} />
          </div>
          <div>
            <div className={styles.kpiValue}>{durationMin}m</div>
            <div className={styles.kpiLabel}>Average Completion Time</div>
          </div>
        </div>
        <div className={styles.kpiCard}>
          <div className={`${styles.kpiIcon} ${styles.red}`}>
            <AlertCircle size={24} />
          </div>
          <div>
            <div className={styles.kpiValue}>{needsRemedial}</div>
            <div className={styles.kpiLabel}>Students Requiring Attention</div>
          </div>
        </div>
      </div>

      <div className={styles.grid}>
        {/* Left Column */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>

          {/* Overview */}
          <div className={styles.card}>
            <h3 className={styles.cardTitle}>Session Overview</h3>
            <div className={styles.overviewGrid}>
              <div className={styles.overviewItem}>
                <span className={styles.overviewLabel}>Subject</span>
                <span className={styles.overviewValue}>{session.courseName}</span>
              </div>
              <div className={styles.overviewItem}>
                <span className={styles.overviewLabel}>Status</span>
                <span className={styles.overviewValue}>{session.status}</span>
              </div>
              <div className={styles.overviewItem}>
                <span className={styles.overviewLabel}>Session Code</span>
                <span className={styles.overviewValue} style={{ fontFamily: 'monospace' }}>{session.sessionCode || 'N/A'}</span>
              </div>
              <div className={styles.overviewItem}>
                <span className={styles.overviewLabel}>Total Questions</span>
                <span className={styles.overviewValue}>{session.questionCount}</span>
              </div>
            </div>
          </div>

          {/* Score Distribution Chart */}
          <div className={styles.card}>
            <h3 className={styles.cardTitle}>Score Distribution</h3>
            {chartData.length > 0 ? (
              <div style={{ height: '240px', width: '100%', display: 'flex', alignItems: 'center' }}>
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={chartData}
                      cx="50%"
                      cy="50%"
                      innerRadius={60}
                      outerRadius={80}
                      paddingAngle={5}
                      dataKey="value"
                    >
                      {chartData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} />
                      ))}
                    </Pie>
                    <Tooltip 
                      formatter={(value: any, name: any) => [`${value} Students`, name]}
                      contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px rgba(0,0,0,0.1)' }}
                    />
                  </PieChart>
                </ResponsiveContainer>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                  {chartData.map((d, i) => (
                    <div key={i} style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                      <div style={{ width: '12px', height: '12px', borderRadius: '50%', backgroundColor: d.color }}></div>
                      <span style={{ fontSize: '0.85rem', color: '#667085' }}>{d.name}: <strong>{d.value}</strong></span>
                    </div>
                  ))}
                </div>
              </div>
            ) : (
              <div style={{ padding: '32px', textAlign: 'center', color: '#667085' }}>No score data available.</div>
            )}
          </div>

          {/* Question Performance */}
          <div className={styles.card}>
            <h3 className={styles.cardTitle}>Question Performance</h3>
            <div style={{ marginTop: '16px' }}>
              {questionProgress.map((qp: any) => {
                const accuracy = qp.totalAnswers > 0 ? (qp.correctAnswers / qp.totalAnswers) * 100 : 0;
                let barClass = '';
                if (accuracy < 40) barClass = styles.danger;
                else if (accuracy <= 70) barClass = styles.warning;

                return (
                  <div key={qp.questionId} className={styles.questionItem}>
                    <div className={styles.questionHeader}>
                      <span style={{ fontWeight: 500, color: '#17223B' }}>Question {qp.questionNumber}</span>
                      <span style={{ color: '#667085', fontSize: '0.8rem' }}>Accuracy: <strong style={{ color: '#17223B' }}>{accuracy.toFixed(0)}%</strong> ({qp.correctAnswers}/{qp.totalAnswers})</span>
                    </div>
                    <div className={styles.progressBarContainer}>
                      <div className={`${styles.progressBarFill} ${barClass}`} style={{ width: `${accuracy}%` }}></div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

        </div>

        {/* Right Column */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>

          {/* Insights */}
          <div className={styles.card}>
            <h3 className={styles.cardTitle}><BrainCircuit size={20} color="#10633B" /> Session Insights</h3>

            <div className={styles.insightBox} style={{ borderLeftColor: '#10633B', marginTop: '16px' }}>
              <div className={styles.insightDesc} style={{ lineHeight: '1.6' }}>
                Students achieved a participation rate of <strong>{kpis.participationPercentage}%</strong> and an average score of <strong>{kpis.averageScore}%</strong>.
                {lowestQuestion && (
                  <span> <strong>Question {lowestQuestion.questionNumber}</strong> had the lowest accuracy at <strong>{lowestAccuracy.toFixed(0)}%</strong>.</span>
                )}
                {needsRemedial > 0 && (
                  <span> <strong>{needsRemedial}</strong> students struggled significantly with the concepts presented.</span>
                )}
                <br /><br />
                <span style={{ color: '#17223B', fontWeight: 600 }}>Recommended Action: </span>
                {lowestQuestion ? `Spend 10-15 minutes revising the concepts from Question ${lowestQuestion.questionNumber} before introducing new topics.` : `Great job! Review any minor gaps and proceed with the syllabus.`}
              </div>
            </div>
          </div>

        </div>
      </div>

      {/* Full Width Table for Students */}
      <div className={styles.card} style={{ marginTop: '24px' }}>
        <h3 className={styles.cardTitle}>Students Requiring Attention</h3>
        <p style={{ color: '#667085', fontSize: '0.85rem', marginBottom: '16px' }}>Showing students who scored below 75% or missed the session.</p>

        <div style={{ overflowX: 'auto' }}>
          <table className={styles.table}>
            <thead>
              <tr>
                <th>Student</th>
                <th>Roll Number</th>
                <th>Score</th>
                <th>Time Taken</th>
                <th>Recommendation</th>
                <th style={{ textAlign: 'right' }}>Action</th>
              </tr>
            </thead>
            <tbody>
              {students.filter((s: any) => !s.hasAttempted || (s.percentage !== null && s.percentage <= 75)).length > 0 ? (
                students.filter((s: any) => !s.hasAttempted || (s.percentage !== null && s.percentage <= 75)).slice(0, 5).map((student: any) => {

                  let rec = 'Review Topic';
                  let recClass = styles.yellow;

                  if (!student.hasAttempted) {
                    rec = 'Missed Session';
                    recClass = styles.blue;
                  } else if (student.percentage < 40) {
                    rec = 'Needs Remedial';
                    recClass = styles.red;
                  }

                  return (
                    <tr key={student.id}>
                      <td style={{ fontWeight: 500 }}>{student.studentName}</td>
                      <td>{student.rollNumber}</td>
                      <td>{student.percentage !== null ? `${student.percentage}%` : '-'}</td>
                      <td>{student.timeTakenSeconds ? `${Math.floor(student.timeTakenSeconds / 60)}m ${student.timeTakenSeconds % 60}s` : '-'}</td>
                      <td>
                        <span className={`${styles.badge} ${recClass}`}>{rec}</span>
                      </td>
                      <td style={{ textAlign: 'right' }}>
                        <button className="btn btn-secondary" style={{ padding: '6px 12px', fontSize: '0.75rem', display: 'inline-flex', alignItems: 'center', gap: '6px' }}>
                          <Eye size={14} /> View Student
                        </button>
                      </td>
                    </tr>
                  )
                })
              ) : (
                <tr>
                  <td colSpan={6} style={{ textAlign: 'center', padding: '32px', color: '#667085' }}>
                    Great job! No students scored below 75%.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
        {students.filter((s: any) => !s.hasAttempted || (s.percentage !== null && s.percentage <= 75)).length > 5 && (
          <div style={{ marginTop: '16px', display: 'flex', justifyContent: 'center' }}>
            <button className="btn btn-secondary" style={{ padding: '8px 24px' }}>
              View All Students
            </button>
          </div>
        )}
      </div>

      {/* Sticky Bottom Bar */}
      <div className={styles.stickyActionBar}>
        <div className={styles.actionLeft}>
          <Link href="/faculty/pulse-sessions" className="btn btn-secondary">
            Back to Pulse Sessions
          </Link>
        </div>
        <div className={styles.actionRight}>
          <Link href="/faculty/concept-gap-analysis" className="btn btn-primary" style={{ textDecoration: 'none' }}>
            <FileText size={18} style={{ marginRight: '8px' }} /> View Concept Gap Analysis
          </Link>
          <button className="btn btn-secondary">
            <Download size={18} style={{ marginRight: '8px' }} /> Download Report
          </button>
        </div>
      </div>
    </div>
  );
}

"use client";
import { apiClient } from '@/lib/apiClient';


import React, { useState, useEffect, useMemo } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { RefreshCw, Download, Book, Target, Clock, Hash, Activity, CheckCircle, Eye, AlignLeft, Calendar, AlertTriangle, Building, GraduationCap, Layers, Users } from 'lucide-react';
import styles from './create-pulse.module.css';

interface Subject {
  id: string;
  name: string;
  department: { id: string, name: string };
  program: { id: string, name: string } | null;
  units: {
    id: string;
    topics: { id: string, topicName: string }[];
  }[];
}

export default function CreatePulseSessionPage() {
  const router = useRouter();

  // Data State
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [profile, setProfile] = useState<unknown>(null);

  // UI State
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  // Form State
  const [formData, setFormData] = useState({
    title: '',
    courseId: '',
    topicId: '',
    departmentId: '',
    programId: '',
    semester: 1,
    section: 'A',
    sessionType: 'MID_CLASS_CHECK',
    date: new Date().toISOString().split('T')[0],
    startTime: '10:00',
    durationMinutes: 10,
    questionType: 'MCQ',
    difficultyLevel: 'MEDIUM',
    questionCount: 5,
    attendanceRule: 'ATTEMPT_REQUIRED',
    resultVisibility: 'STUDENTS_AFTER_SESSION',
  });

  const [sessionCode, setSessionCode] = useState('');
  const [qrCodeUrl, setQrCodeUrl] = useState('');
  const [publishImmediately, setPublishImmediately] = useState(false);

  useEffect(() => {
    async function fetchData() {
      try {
        const [profileRes, subjectsRes] = await Promise.all([
          apiClient.get('/api/faculty/profile'),
          apiClient.get('/api/faculty/subjects?limit=100')
        ]);

        if (profileRes.ok) {
          const profileJson = profileRes;
          setProfile(profileJson.data);
          setFormData(prev => ({ ...prev, departmentId: profileJson.data.department?.id || '' }));
        }

        if (subjectsRes.ok) {
          const subjectsJson = subjectsRes;
          setSubjects(subjectsJson.data?.subjects || []);
        }
      } catch (err) {
        console.error('Failed to fetch initial data', err);
        setError('Failed to load required data. Please refresh.');
      } finally {
        setLoading(false);
      }
    }
    fetchData();
  }, []);

  const selectedSubject = useMemo(() => 
    subjects.find(s => s.id === formData.courseId), 
  [subjects, formData.courseId]);

  const allTopics = useMemo(() => {
    if (!selectedSubject) return [];
    return selectedSubject.units.flatMap(u => u.topics) || [];
  }, [selectedSubject]);

  // Sync program when subject changes
  useEffect(() => {
    if (selectedSubject) {
      setFormData(prev => ({
        ...prev,
        programId: selectedSubject.program?.id || prev.programId,
      }));
    }
  }, [selectedSubject]);

  const handleChange = (field: string, value: unknown) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const generateLocalCode = () => {
    const code = 'PULSE-' + Math.random().toString(36).substring(2, 6).toUpperCase();
    setSessionCode(code);
    setQrCodeUrl(`https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=mysession_${code}`);
  };

  const validateForm = () => {
    if (!formData.title) return 'Session Name is required.';
    if (!formData.courseId) return 'Subject is required.';
    if (!formData.topicId) return 'Topic is required.';
    if (!formData.departmentId) return 'Department is required.';
    if (!formData.date) return 'Date is required.';
    if (!formData.startTime) return 'Start Time is required.';
    return null;
  };

  const handleSubmit = async (e: React.FormEvent, asDraft: boolean = false) => {
    e.preventDefault();
    const validationError = validateForm();
    if (validationError) {
      setError(validationError);
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }

    setSaving(true);
    setError('');

    try {
      // 1. Create Session
      const payload = { ...formData };

      const sessionData = await apiClient.post('/api/faculty/pulse-sessions', payload);
      const newSessionId = sessionData.data.id;

      // 2. Generate Code if requested
      if (sessionCode) {
        await apiClient.post(`/api/faculty/pulse-sessions/${newSessionId}/generate-code`);
        await apiClient.post(`/api/faculty/pulse-sessions/${newSessionId}/generate-qr`);
      }

      // 3. Publish if requested (and not saving as pure draft)
      if (!asDraft && publishImmediately) {
        await apiClient.post(`/api/faculty/pulse-sessions/${newSessionId}/publish`);
      }

      // 4. Redirect
      router.push('/faculty/pulse-sessions');
      router.refresh();

    } catch (err: unknown) {
      setError(err.message || 'An unexpected error occurred.');
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } finally {
      setSaving(false);
    }
  };

  const missingFields = useMemo(() => {
    const missing = [];
    if (!formData.title) missing.push('Session Name');
    if (!formData.courseId) missing.push('Subject');
    if (!formData.topicId) missing.push('Topic');
    if (!formData.departmentId) missing.push('Department');
    if (!formData.date) missing.push('Date');
    if (!formData.startTime) missing.push('Start Time');
    return missing;
  }, [formData]);

  const isReady = missingFields.length === 0;

  if (loading) {
    return <div className={styles.container} style={{ alignItems: 'center', justifyContent: 'center' }}>Loading...</div>;
  }

  return (
    <div className={`dashboard-scroll ${styles.container}`}>
      {/* Header */}
      <div className="page-header">
        <div className="page-title-section">
          <h1 className="page-title" style={{ marginTop: '4px' }}>Create Pulse Session</h1>
          <div className="page-tags">
            <span style={{ color: '#667085', fontSize: '0.85rem' }}>
              Configure and launch a live pulse assessment for your class.
            </span>
          </div>
        </div>
        <div className="page-actions">
          <button className="btn btn-secondary" onClick={() => router.push('/faculty/pulse-sessions')}>
            &larr; View All Sessions
          </button>
        </div>
      </div>

      {error && (
        <div style={{ padding: '12px 16px', backgroundColor: '#FEE2E2', color: '#DC2626', borderRadius: '8px', border: '1px solid #FCA5A5' }}>
          {error}
        </div>
      )}

      <div className={styles.layout}>
        {/* Main Column */}
        <div className={styles.mainColumn}>

          {/* Section 1: Session Information */}
          <div className={styles.card}>
            <div className={styles.cardHeader}>
              <div className={styles.stepNumber}>1</div>
              <div>
                <h3 className={styles.cardTitle}>Session Information</h3>
                <p className={styles.cardSubtitle}>Basic details about this pulse session</p>
              </div>
            </div>

            <div className={styles.formGrid}>
              <div className={styles.formGroup}>
                <label className={styles.formLabel}>Session Name <span className={styles.required}>*</span></label>
                <input 
                  type="text" 
                  className={styles.input} 
                  placeholder="e.g. Tree Traversal Check"
                  value={formData.title}
                  onChange={(e) => handleChange('title', e.target.value)}
                />
              </div>

              <div className={styles.formGroup}>
                <label className={styles.formLabel}>Subject <span className={styles.required}>*</span></label>
                <select 
                  className={styles.select}
                  value={formData.courseId}
                  onChange={(e) => handleChange('courseId', e.target.value)}
                >
                  <option value="">Select Subject</option>
                  {subjects.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
              </div>

              <div className={styles.formGroup}>
                <label className={styles.formLabel}>Topic <span className={styles.required}>*</span></label>
                <select 
                  className={styles.select}
                  value={formData.topicId}
                  onChange={(e) => handleChange('topicId', e.target.value)}
                  disabled={!formData.courseId}
                >
                  <option value="">Select Topic</option>
                  {allTopics.map(t => <option key={t.id} value={t.id}>{t.topicName}</option>)}
                </select>
              </div>

              <div className={styles.formGroup}>
                <label className={styles.formLabel}>Department <span className={styles.required}>*</span></label>
                <select 
                  className={styles.select}
                  value={formData.departmentId}
                  onChange={(e) => handleChange('departmentId', e.target.value)}
                >
                  <option value="">Select Department</option>
                  {profile?.department && <option value={profile.department.id}>{profile.department.name}</option>}
                </select>
              </div>

              <div className={styles.formGroup}>
                <label className={styles.formLabel}>Program <span className={styles.required}>*</span></label>
                <select 
                  className={styles.select}
                  value={formData.programId}
                  onChange={(e) => handleChange('programId', e.target.value)}
                >
                  <option value="">Select Program</option>
                  {selectedSubject?.program && <option value={selectedSubject.program.id}>{selectedSubject.program.name}</option>}
                </select>
              </div>

              <div className={styles.formGroup}>
                <label className={styles.formLabel}>Semester <span className={styles.required}>*</span></label>
                <select 
                  className={styles.select}
                  value={formData.semester}
                  onChange={(e) => handleChange('semester', parseInt(e.target.value))}
                >
                  {[1,2,3,4,5,6,7,8].map(s => <option key={s} value={s}>Semester {s}</option>)}
                </select>
              </div>

              <div className={styles.formGroup}>
                <label className={styles.formLabel}>Section</label>
                <select 
                  className={styles.select}
                  value={formData.section}
                  onChange={(e) => handleChange('section', e.target.value)}
                >
                  <option value="A">Section A</option>
                  <option value="B">Section B</option>
                  <option value="C">Section C</option>
                </select>
              </div>

              <div className={styles.formGroup}>
                <label className={styles.formLabel}>Session Type <span className={styles.required}>*</span></label>
                <select 
                  className={styles.select}
                  value={formData.sessionType}
                  onChange={(e) => handleChange('sessionType', e.target.value)}
                >
                  <option value="MID_CLASS_CHECK">Mid-Class Check</option>
                  <option value="END_OF_CLASS_CHECK">End-of-Class Check</option>
                  <option value="WEEKLY_REVISION">Weekly Revision</option>
                  <option value="LAB_UNDERSTANDING_CHECK">Lab Assessment</option>
                  <option value="PLACEMENT_TRAINING_SESSION">Placement Practice</option>
                  <option value="TUTORIAL_SESSION">Tutorial Session</option>
                  <option value="REMEDIAL_SESSION">Remedial Session</option>
                  <option value="CONTEST_PREPARATION_SESSION">Contest Practice</option>
                </select>
              </div>

              <div className={styles.formGroup}>
                <label className={styles.formLabel}>Date <span className={styles.required}>*</span></label>
                <input 
                  type="date" 
                  className={styles.input} 
                  value={formData.date}
                  onChange={(e) => handleChange('date', e.target.value)}
                />
              </div>

              <div className={styles.formGroup}>
                <label className={styles.formLabel}>Time <span className={styles.required}>*</span></label>
                <input 
                  type="time" 
                  className={styles.input} 
                  value={formData.startTime}
                  onChange={(e) => handleChange('startTime', e.target.value)}
                />
              </div>

              <div className={styles.formGroup}>
                <label className={styles.formLabel}>Duration <span className={styles.required}>*</span></label>
                <select 
                  className={styles.select}
                  value={formData.durationMinutes}
                  onChange={(e) => handleChange('durationMinutes', parseInt(e.target.value))}
                >
                  <option value={5}>5 Minutes</option>
                  <option value={10}>10 Minutes</option>
                  <option value={15}>15 Minutes</option>
                  <option value={30}>30 Minutes</option>
                  <option value={60}>60 Minutes</option>
                </select>
                <span className={styles.hintText}>Duration should be between 5 to 60 minutes.</span>
              </div>
            </div>
          </div>

          {/* Section 2: Assessment Configuration */}
          <div className={styles.card}>
            <div className={styles.cardHeader}>
              <div className={styles.stepNumber}>2</div>
              <div>
                <h3 className={styles.cardTitle}>Assessment Configuration</h3>
                <p className={styles.cardSubtitle}>Define the assessment parameters</p>
              </div>
            </div>

            <div className={styles.formGroup} style={{ marginBottom: '24px' }}>
              <label className={styles.formLabel}>Question Type <span className={styles.required}>*</span></label>
              <div className={styles.radioGroup}>
                <div 
                  className={`${styles.radioCard} ${formData.questionType === 'MCQ' ? styles.active : ''}`}
                  onClick={() => handleChange('questionType', 'MCQ')}
                >
                  <div className={styles.radioCircle}></div>
                  <CheckCircle size={16} color={formData.questionType === 'MCQ' ? '#10633B' : '#667085'} />
                  <span>MCQ</span>
                </div>
                <div 
                  className={`${styles.radioCard} ${formData.questionType === 'TRUE_FALSE' ? styles.active : ''}`}
                  onClick={() => handleChange('questionType', 'TRUE_FALSE')}
                >
                  <div className={styles.radioCircle}></div>
                  <span>True / False</span>
                </div>
                <div 
                  className={`${styles.radioCard} ${formData.questionType === 'SHORT_ANSWER' ? styles.active : ''}`}
                  onClick={() => handleChange('questionType', 'SHORT_ANSWER')}
                >
                  <div className={styles.radioCircle}></div>
                  <span>Short Answer</span>
                </div>
              </div>
            </div>

            <div className={styles.formGrid}>
              <div className={styles.formGroup}>
                <label className={styles.formLabel}>Difficulty Level <span className={styles.required}>*</span></label>
                <select 
                  className={styles.select}
                  value={formData.difficultyLevel}
                  onChange={(e) => handleChange('difficultyLevel', e.target.value)}
                >
                  <option value="EASY">Easy</option>
                  <option value="MEDIUM">Medium</option>
                  <option value="HARD">Hard</option>
                  <option value="MIXED">Mixed</option>
                </select>
              </div>

              <div className={styles.formGroup}>
                <label className={styles.formLabel}>Number of Questions <span className={styles.required}>*</span></label>
                <input 
                  type="number" 
                  className={styles.input} 
                  min={1} 
                  max={50}
                  value={formData.questionCount}
                  onChange={(e) => handleChange('questionCount', parseInt(e.target.value))}
                />
              </div>

              <div className={styles.formGroup}>
                <label className={styles.formLabel}>Attendance Rule <span className={styles.required}>*</span></label>
                <select 
                  className={styles.select}
                  value={formData.attendanceRule}
                  onChange={(e) => handleChange('attendanceRule', e.target.value)}
                >
                  <option value="ATTEMPT_REQUIRED">Mandatory</option>
                  <option value="BOTH">Optional</option>
                </select>
              </div>

              <div className={styles.formGroup}>
                <label className={styles.formLabel}>Result Visibility <span className={styles.required}>*</span></label>
                <select 
                  className={styles.select}
                  value={formData.resultVisibility}
                  onChange={(e) => handleChange('resultVisibility', e.target.value)}
                >
                  <option value="IMMEDIATE">Immediately</option>
                  <option value="STUDENTS_AFTER_SESSION">After Session Ends</option>
                  <option value="FACULTY_ONLY">Faculty Only</option>
                </select>
                <span className={styles.hintText}>Control when students can see their results.</span>
              </div>
            </div>
          </div>

          {/* Section 3: Session Settings */}
          <div className={styles.card}>
            <div className={styles.cardHeader}>
              <div className={styles.stepNumber}>3</div>
              <div>
                <h3 className={styles.cardTitle}>Session Settings</h3>
                <p className={styles.cardSubtitle}>Additional settings and publishing options</p>
              </div>
            </div>

            <div className={styles.settingsGrid}>
              {/* Column 1 */}
              <div className={styles.settingsColumn}>
                <div className={styles.formGroup}>
                  <label className={styles.formLabel}>Session Code</label>
                  <div className={styles.flexRow}>
                    <input 
                      type="text" 
                      className={styles.input} 
                      value={sessionCode} 
                      placeholder="Auto generated"
                      disabled 
                      style={{ flex: 1, fontFamily: 'monospace', letterSpacing: '1px' }}
                    />
                    <button type="button" className={styles.iconButton} onClick={generateLocalCode} title="Generate Code">
                      <RefreshCw size={18} />
                    </button>
                  </div>
                  <span className={styles.hintText}>A unique code generated for students to join.</span>
                </div>
              </div>

              {/* Column 2 */}
              <div className={styles.settingsCard}>
                <h4 className={styles.settingsCardTitle}>QR Code</h4>
                <div className={styles.qrContainer}>
                  <div className={styles.qrBox}>
                    {qrCodeUrl ? (
                      <img src={qrCodeUrl} alt="QR Code" width={100} height={100} />
                    ) : (
                      <span style={{ color: '#ccc', fontSize: '12px' }}>No QR generated</span>
                    )}
                  </div>
                  <button 
                    type="button" 
                    className="btn btn-outline" 
                    disabled={!qrCodeUrl} 
                    style={{ width: '120px', justifyContent: 'center' }}
                  >
                    <Download size={16} /> Download
                  </button>
                  <span className={styles.hintText} style={{ textAlign: 'center', marginTop: '4px' }}>
                    Students can scan this QR code to join.
                  </span>
                </div>
              </div>

              {/* Column 3 */}
              <div className={styles.settingsCard}>
                <h4 className={styles.settingsCardTitle}>Publishing Options</h4>
                <div className={styles.toggleList}>
                  <div className={styles.toggleItem}>
                    <div className={styles.toggleRow}>
                      <div 
                        className={`${styles.toggleSwitch} ${publishImmediately ? styles.active : ''}`}
                        onClick={() => setPublishImmediately(true)}
                      >
                        <div className={styles.toggleKnob}></div>
                      </div>
                      Publish Immediately
                    </div>
                    <span className={styles.hintText}>Students can join as soon as the session is published.</span>
                  </div>

                  <div className={styles.toggleDivider}></div>

                  <div className={styles.toggleItem}>
                    <div className={styles.toggleRow}>
                      <div 
                        className={`${styles.toggleSwitch} ${!publishImmediately ? styles.active : ''}`}
                        onClick={() => setPublishImmediately(false)}
                      >
                        <div className={styles.toggleKnob}></div>
                      </div>
                      Save as Draft
                    </div>
                    <span className={styles.hintText}>Save now and publish later.</span>
                  </div>
                </div>
              </div>
            </div>
          </div>



        </div>

        {/* Right Sidebar */}
        <div className={styles.sideColumn}>
          <div className={styles.card}>
            <h3 className={styles.cardTitle}>What happens next?</h3>

            <div className={styles.timeline}>
              <div className={styles.timelineItem}>
                <div className={styles.timelineIcon}>1</div>
                <div className={styles.timelineContent}>
                  <div className={styles.timelineTitle}>Publish Session</div>
                  <div className={styles.timelineDesc}>Once published, students can see the session and join using the code or QR.</div>
                </div>
              </div>

              <div className={styles.timelineItem}>
                <div className={styles.timelineIcon}>2</div>
                <div className={styles.timelineContent}>
                  <div className={styles.timelineTitle}>Students Join</div>
                  <div className={styles.timelineDesc}>Students enter the session code or scan the QR to join.</div>
                </div>
              </div>

              <div className={styles.timelineItem}>
                <div className={styles.timelineIcon}>3</div>
                <div className={styles.timelineContent}>
                  <div className={styles.timelineTitle}>Start Session</div>
                  <div className={styles.timelineDesc}>You start the session when all students are ready.</div>
                </div>
              </div>

              <div className={styles.timelineItem}>
                <div className={styles.timelineIcon}>4</div>
                <div className={styles.timelineContent}>
                  <div className={styles.timelineTitle}>Live Assessment</div>
                  <div className={styles.timelineDesc}>Students answer questions in real-time.</div>
                </div>
              </div>

              <div className={styles.timelineItem}>
                <div className={styles.timelineIcon}>5</div>
                <div className={styles.timelineContent}>
                  <div className={styles.timelineTitle}>Session Summary</div>
                  <div className={styles.timelineDesc}>View summary and concept gap analysis after completion.</div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Sticky Bottom Action Bar */}
      <div className={styles.stickyActionBar}>
        <div className={styles.actionBarLeft}>
          <span className={styles.hintText} style={{ fontWeight: 600, color: '#475569' }}>
            Review the information above before publishing. You can save this session as a draft and continue editing later.
          </span>
        </div>
        <div className={styles.actionBarRight}>
          <button 
            type="button" 
            className="btn btn-secondary"
            onClick={() => router.push('/faculty/pulse-sessions')}
            disabled={saving}
          >
            Cancel
          </button>
          <button 
            type="button" 
            className="btn btn-outline"
            onClick={(e) => handleSubmit(e, true)}
            disabled={saving}
          >
            Save Draft
          </button>
          <div style={{ position: 'relative' }} title={!isReady ? "Complete all required fields before publishing" : ""}>
            <button 
              type="submit" 
              className="btn btn-primary"
              disabled={saving || !isReady}
              onClick={(e) => {
                if (isReady) handleSubmit(e, false);
              }}
              style={!isReady ? { opacity: 0.5, cursor: 'not-allowed' } : {}}
            >
              {saving ? 'Publishing...' : 'Publish Session'}
            </button>
          </div>
        </div>
      </div>

      {saving && (
        <div className={styles.loadingOverlay}>
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '16px' }}>
            <Activity size={32} color="#10633B" style={{ animation: 'pulse 1.5s infinite' }} />
            <h3 style={{ color: '#17223B' }}>Saving Pulse Session...</h3>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";
import { apiClient } from '@/lib/apiClient';


import React, { useState, useEffect, useCallback } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { 
  PlusCircle, 
  Calendar, 
  Radio, 
  Clock, 
  CheckCircle,
  MoreVertical,
  Eye,
  Edit,
  Copy,
  QrCode,
  Hash,
  PlayCircle,
  StopCircle,
  Trash2,
  Activity,
  FileText,
  Download,
  Users
} from 'lucide-react';
import styles from './pulse-sessions.module.css';

export default function PulseSessionsPage() {
  const [sessions, setSessions] = useState<unknown[]>([]);
  const [summary, setSummary] = useState({ total: 0, live: 0, upcoming: 0, completed: 0 });
  const [loading, setLoading] = useState(true);
  const [activeMenu, setActiveMenu] = useState<string | null>(null);
  const [activeLiveSession, setActiveLiveSession] = useState<unknown | null>(null);
  const [elapsedTime, setElapsedTime] = useState('00:00');
  const [showStartDialog, setShowStartDialog] = useState<string | null>(null);
  const router = useRouter();

  // Pagination state
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);

  // Filters state
  const [search, setSearch] = useState('');
  const [subject, setSubject] = useState('');
  const [type, setType] = useState('');
  const [status, setStatus] = useState('');
  const [semester, setSemester] = useState('');

  const fetchSummary = async () => {
    try {
      const res = await apiClient.get('/api/faculty/pulse-sessions/summary');
      if (res.ok) {
        const json = res;
        setSummary(json.data);
      }
    } catch (e) {
      console.error(e);
    }
  };

  const fetchSessions = useCallback(async () => {
    setLoading(true);
    try {
      const query = new URLSearchParams();
      query.append('page', page.toString());
      query.append('limit', '10');
      if (search) query.append('search', search);
      if (subject) query.append('courseId', subject);
      if (type) query.append('sessionType', type);
      if (status) query.append('status', status.toUpperCase());
      if (semester) query.append('semester', semester);

      const res = await apiClient.get(`/api/faculty/pulse-sessions?${query.toString()}`);
      if (res.ok) {
        const json = res;
        setSessions(json.data?.sessions || []);
        setTotalPages(json.data?.pagination?.totalPages || 1);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  }, [page, search, subject, type, status, semester]);

  const fetchActiveLiveSession = async () => {
    try {
      const res = await apiClient.get('/api/faculty/pulse-sessions?status=LIVE&limit=1');
      if (res.ok) {
        const json = res;
        if (json.data?.sessions && json.data.sessions.length > 0) {
          setActiveLiveSession(json.data.sessions[0]);
        } else {
          setActiveLiveSession(null);
        }
      }
    } catch (e) {
      console.error(e);
    }
  };

  useEffect(() => {
    fetchSummary();
    fetchActiveLiveSession();
  }, []);

  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (activeLiveSession) {
      const startTime = new Date(activeLiveSession.timerActualStartTime || activeLiveSession.createdAt).getTime();
      interval = setInterval(() => {
        const now = Date.now();
        const diff = Math.floor((now - startTime) / 1000);
        const m = Math.floor(diff / 60).toString().padStart(2, '0');
        const s = (diff % 60).toString().padStart(2, '0');
        setElapsedTime(`${m}:${s}`);
      }, 1000);
    }
    return () => {
      if (interval) clearInterval(interval);
    }
  }, [activeLiveSession]);

  useEffect(() => {
    fetchSessions();
  }, [fetchSessions]);

  const toggleMenu = (id: string) => {
    if (activeMenu === id) {
      setActiveMenu(null);
    } else {
      setActiveMenu(id);
    }
  };

  const resetFilters = () => {
    setSearch('');
    setSubject('');
    setType('');
    setStatus('');
    setSemester('');
    setPage(1);
  };

  const handleAction = async (id: string, action: string) => {
    try {
      if (action === 'DELETE') {
        if (!confirm('Are you sure you want to delete this session?')) return;
        await apiClient.delete(`/api/faculty/pulse-sessions/${id}`);
      } else {
        await apiClient.post(`/api/faculty/pulse-sessions/${id}/${action}`);
      }
      if (action === 'start') {
        setShowStartDialog(null);
        router.push(`/faculty/pulse-sessions/${id}/live`);
        return;
      }
      if (action === 'end') {
        if (!confirm('End Session?')) return;
        router.push(`/faculty/pulse-sessions/${id}/summary`);
        return; // Redirecting, no need to refetch
      }
      fetchSessions();
      fetchSummary();
      setActiveMenu(null);
    } catch (e) {
      console.error(e);
    }
  };

  const getStatusBadge = (statusStr: string) => {
    const s = statusStr?.toUpperCase() || 'DRAFT';
    switch (s) {
      case 'DRAFT': return <span className={`${styles.badge} ${styles.badgeDraft}`}>Draft</span>;
      case 'PUBLISHED': return <span className={`${styles.badge} ${styles.badgePublished}`}>Published</span>;
      case 'LIVE': return <span className={`${styles.badge} ${styles.badgeLive}`}><span style={{width: '6px', height: '6px', borderRadius: '50%', backgroundColor: '#166534', marginRight: '4px'}}></span> Live</span>;
      case 'UPCOMING': return <span className={`${styles.badge} ${styles.badgePublished}`}>Upcoming</span>;
      case 'CLOSED': return <span className={`${styles.badge} ${styles.badgeClosed}`}>Closed</span>;
      case 'EVALUATED': return <span className={`${styles.badge} ${styles.badgeEvaluated}`}>Evaluated</span>;
      case 'ARCHIVED': return <span className={`${styles.badge} ${styles.badgeArchived}`}>Archived</span>;
      default: return <span className={`${styles.badge} ${styles.badgeDraft}`}>{statusStr}</span>;
    }
  };

  const formatType = (t: string) => {
    if (!t) return 'Unknown';
    return t.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  };

  return (
    <div className="dashboard-scroll" onClick={() => setActiveMenu(null)}>
      {/* Page Header */}
      <div className="page-header">
        <div className="page-title-section">

          <h1 className="page-title" style={{ marginTop: '4px' }}>Pulse Sessions</h1>
          <div className="page-tags">
            <span style={{ color: '#667085', fontSize: '0.85rem' }}>
              Create, manage and monitor classroom pulse assessment sessions.
            </span>
          </div>
        </div>
        <div className="page-actions">
          <Link href="/faculty/pulse-sessions/create" className="btn btn-primary" style={{ textDecoration: 'none' }}>
            <PlusCircle size={18} /> Create Pulse Session
          </Link>
        </div>
      </div>

      {activeLiveSession && (
        <div style={{
          backgroundColor: '#EEF7F1',
          border: '1px solid #166534',
          borderRadius: '12px',
          padding: '20px 32px',
          marginBottom: '24px',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.05)'
        }}>
          <div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px' }}>
              <div style={{ width: '10px', height: '10px', borderRadius: '50%', backgroundColor: '#166534', animation: 'pulse 2s infinite' }}></div>
              <span style={{ color: '#166534', fontWeight: '600', fontSize: '0.9rem', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Live Session In Progress</span>
            </div>
            <h3 style={{ margin: '0 0 8px 0', fontSize: '1.25rem', color: '#17223B' }}>{activeLiveSession.title}</h3>
            <div style={{ display: 'flex', gap: '24px', color: '#667085', fontSize: '0.95rem' }}>
              <span style={{ display: 'flex', alignItems: 'center', gap: '6px' }}><Users size={16} /> {activeLiveSession.participations?.length || 0} Students Joined</span>
              <span style={{ display: 'flex', alignItems: 'center', gap: '6px' }}><Clock size={16} /> Elapsed Time: {elapsedTime}</span>
            </div>
          </div>
          <Link href={`/faculty/pulse-sessions/${activeLiveSession.id}/live`} className="btn btn-primary" style={{ textDecoration: 'none', backgroundColor: '#10633B', padding: '12px 24px', fontSize: '1rem' }}>
            Monitor Session
          </Link>
        </div>
      )}

      <div className={styles.container}>
        {/* KPI Cards */}
        <div className={styles.kpiGrid}>
          {/* Card 1: Total */}
          <div className={`${styles.kpiCard} ${styles.cardTotal}`}>
            <div className={`${styles.kpiIconWrapper} ${styles.iconTotal}`}>
              <Calendar size={24} />
            </div>
            <div className={styles.kpiContent}>
              <div className={styles.kpiLabel}>Total Sessions</div>
              <div className={styles.kpiValue}>{summary.total}</div>
            </div>
          </div>

          {/* Card 2: Live */}
          <div className={`${styles.kpiCard} ${styles.cardLive}`}>
            <div className={`${styles.kpiIconWrapper} ${styles.iconLive}`}>
              <Radio size={24} />
            </div>
            <div className={styles.kpiContent}>
              <div className={styles.kpiLabel}>Live Sessions</div>
              <div className={styles.kpiValue}>{summary.live}</div>
            </div>
          </div>

          {/* Card 3: Upcoming */}
          <div className={`${styles.kpiCard} ${styles.cardUpcoming}`}>
            <div className={`${styles.kpiIconWrapper} ${styles.iconUpcoming}`}>
              <Clock size={24} />
            </div>
            <div className={styles.kpiContent}>
              <div className={styles.kpiLabel}>Upcoming</div>
              <div className={styles.kpiValue}>{summary.upcoming}</div>
            </div>
          </div>

          {/* Card 4: Completed */}
          <div className={`${styles.kpiCard} ${styles.cardCompleted}`}>
            <div className={`${styles.kpiIconWrapper} ${styles.iconCompleted}`}>
              <CheckCircle size={24} />
            </div>
            <div className={styles.kpiContent}>
              <div className={styles.kpiLabel}>Completed</div>
              <div className={styles.kpiValue}>{summary.completed}</div>
            </div>
          </div>
        </div>

        {/* Filter Bar */}
        <div className={styles.filters}>
          <div className={styles.filterGroup} style={{ flex: 2 }}>
            <label>Search Session</label>
            <input 
              type="text" 
              className={styles.input} 
              placeholder="Search by name or code..."
              value={search}
              onChange={(e) => { setSearch(e.target.value); setPage(1); }}
            />
          </div>
          <div className={styles.filterGroup}>
            <label>Subject</label>
            <select className={styles.select} value={subject} onChange={(e) => { setSubject(e.target.value); setPage(1); }}>
              <option value="">All Subjects</option>
              <option value="CS201">Data Structures (CS201)</option>
              <option value="CS305">Database Systems (CS305)</option>
              <option value="CS401">Web Development (CS401)</option>
            </select>
          </div>
          <div className={styles.filterGroup}>
            <label>Session Type</label>
            <select className={styles.select} value={type} onChange={(e) => { setType(e.target.value); setPage(1); }}>
              <option value="">All Types</option>
              <option value="START_OF_CLASS_CHECK">Start-of-Class Check</option>
              <option value="MID_CLASS_CHECK">Mid-Class Check</option>
              <option value="END_OF_CLASS_CHECK">End-of-Class Check</option>
              <option value="FEEDBACK">Feedback</option>
            </select>
          </div>
          <div className={styles.filterGroup}>
            <label>Status</label>
            <select className={styles.select} value={status} onChange={(e) => { setStatus(e.target.value); setPage(1); }}>
              <option value="">All Statuses</option>
              <option value="DRAFT">Draft</option>
              <option value="PUBLISHED">Published</option>
              <option value="LIVE">Live</option>
              <option value="CLOSED">Closed</option>
              <option value="EVALUATED">Evaluated</option>
            </select>
          </div>
          <div className={styles.filterGroup}>
            <label>Semester</label>
            <select className={styles.select} value={semester} onChange={(e) => { setSemester(e.target.value); setPage(1); }}>
              <option value="">All Semesters</option>
              {[1,2,3,4,5,6,7,8].map(s => <option key={s} value={s}>Semester {s}</option>)}
            </select>
          </div>
          <div>
            <button className="btn btn-secondary" style={{ height: '40px' }} onClick={resetFilters}>
              Reset
            </button>
          </div>
        </div>

        {/* Main Table */}
        <div className={styles.tableCard}>
          <div className={styles.tableHeader}>
            <span className={styles.tableTitle}>Recent Pulse Sessions</span>
          </div>

          <table className={styles.table}>
            <thead>
              <tr>
                <th>Session Name</th>
                <th>Subject</th>
                <th>Session Type</th>
                <th>Session Code</th>
                <th>Date</th>
                <th>Time</th>
                <th>Status</th>
                <th>Participants</th>
                <th style={{ textAlign: 'center' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr><td colSpan={9} style={{ textAlign: 'center', padding: '40px' }}>Loading sessions...</td></tr>
              ) : sessions.length > 0 ? (
                sessions.map((session) => (
                  <tr key={session.id}>
                    <td style={{ fontWeight: 600 }}>{session.title}</td>
                    <td>{session.course?.name || 'Unknown Subject'}</td>
                    <td>{formatType(session.sessionType)}</td>
                    <td style={{ fontFamily: 'monospace' }}>{session.sessionCode || '-'}</td>
                    <td>{new Date(session.date).toLocaleDateString()}</td>
                    <td>{session.startTime}</td>
                    <td>{getStatusBadge(session.status)}</td>
                    <td>-</td>
                    <td>
                      {session.status === 'LIVE' ? (
                        <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
                          <Link 
                            href={`/faculty/pulse-sessions/${session.id}/live`}
                            className="btn btn-primary"
                            style={{ textDecoration: 'none', backgroundColor: '#10633B', display: 'inline-flex', alignItems: 'center', gap: '6px', fontSize: '0.85rem', padding: '6px 12px' }}
                          >
                            <div style={{ width: '8px', height: '8px', borderRadius: '50%', backgroundColor: '#4ADE80', animation: 'pulse 2s infinite' }}></div>
                            Monitor Live
                          </Link>
                          <button 
                            className="btn btn-secondary"
                            onClick={() => handleAction(session.id, 'end')}
                            style={{ fontSize: '0.85rem', padding: '6px 12px', color: '#DC2626', borderColor: '#DC2626' }}
                          >
                            End Session
                          </button>
                        </div>
                      ) : (
                        <div className={styles.actionMenu}>
                          <button 
                            className={styles.actionButton} 
                            onClick={(e) => { e.stopPropagation(); toggleMenu(session.id); }}
                          >
                            <MoreVertical size={18} />
                          </button>

                          {activeMenu === session.id && (
                            <div className={styles.dropdownMenu}>
                              {session.status === 'DRAFT' && (
                                <>
                                  <button className={styles.dropdownItem}>
                                    <Edit size={16} /> Edit
                                  </button>
                                  <button className={styles.dropdownItem}>
                                    <Copy size={16} /> Duplicate
                                  </button>
                                  <div style={{ height: '1px', backgroundColor: '#E7E3DB', margin: '4px 0' }}></div>
                                  <button className={styles.dropdownItem} onClick={() => handleAction(session.id, 'publish')}>
                                    <CheckCircle size={16} /> Publish
                                  </button>
                                  <button className={`${styles.dropdownItem} ${styles.danger}`} onClick={() => handleAction(session.id, 'DELETE')}>
                                    <Trash2 size={16} /> Delete
                                  </button>
                                </>
                              )}

                              {session.status === 'PUBLISHED' && (
                                <>
                                  <button className={styles.dropdownItem}>
                                    <Eye size={16} /> View
                                  </button>
                                  <button className={styles.dropdownItem} onClick={() => handleAction(session.id, 'generate-qr')}>
                                    <QrCode size={16} /> Generate QR
                                  </button>
                                  <button className={styles.dropdownItem} onClick={() => handleAction(session.id, 'generate-code')}>
                                    <Hash size={16} /> Copy Session Code
                                  </button>
                                  <div style={{ height: '1px', backgroundColor: '#E7E3DB', margin: '4px 0' }}></div>
                                  <button className={styles.dropdownItem} style={{ color: '#166534' }} onClick={() => setShowStartDialog(session.id)}>
                                    <PlayCircle size={16} /> Start Session
                                  </button>
                                </>
                              )}

                              {['CLOSED', 'COMPLETED', 'ARCHIVED'].includes(session.status) && (
                                <>
                                  <Link href={`/faculty/pulse-sessions/${session.id}/summary`} className={styles.dropdownItem} style={{ textDecoration: 'none', color: 'inherit' }}>
                                    <Activity size={16} /> View Summary
                                  </Link>
                                  <button className={styles.dropdownItem}>
                                    <Download size={16} /> Download Report
                                  </button>
                                  <Link href={`/faculty/concept-gap-analysis`} className={styles.dropdownItem} style={{ textDecoration: 'none', color: 'inherit' }}>
                                    <FileText size={16} /> View Concept Gap Analysis
                                  </Link>
                                  <button className={styles.dropdownItem}>
                                    <Copy size={16} /> Duplicate Session
                                  </button>
                                </>
                              )}
                            </div>
                          )}
                        </div>
                      )}
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={9}>
                    <div className={styles.emptyState}>
                      <Activity size={48} className={styles.emptyStateIcon} />
                      <h3 className={styles.emptyStateTitle}>No Pulse Sessions Yet</h3>
                      <p className={styles.emptyStateDesc}>
                        Create your first classroom pulse session to begin collecting student understanding and live feedback.
                      </p>
                      <Link href="/faculty/pulse-sessions/create" className="btn btn-primary" style={{ textDecoration: 'none' }}>
                        <PlusCircle size={18} /> Create Pulse Session
                      </Link>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>

          {!loading && sessions.length > 0 && (
            <div className={styles.pagination}>
              <button 
                className={styles.pageBtn} 
                disabled={page === 1}
                onClick={() => setPage(p => Math.max(1, p - 1))}
              >
                Previous
              </button>

              {Array.from({ length: totalPages }).map((_, i) => (
                <button 
                  key={i} 
                  className={`${styles.pageBtn} ${page === i + 1 ? styles.active : ''}`}
                  onClick={() => setPage(i + 1)}
                >
                  {i + 1}
                </button>
              ))}

              <button 
                className={styles.pageBtn}
                disabled={page === totalPages}
                onClick={() => setPage(p => Math.min(totalPages, p + 1))}
              >
                Next
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Start Session Dialog */}
      {showStartDialog && (
        <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.5)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ backgroundColor: '#fff', borderRadius: '12px', padding: '24px', width: '100%', maxWidth: '400px', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}>
            <h3 style={{ margin: '0 0 12px 0', fontSize: '1.25rem', color: '#17223B' }}>Start Session</h3>
            <p style={{ color: '#667085', marginBottom: '24px', lineHeight: '1.5' }}>
              Start this session now? Students will be able to join and submit answers.
            </p>
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px' }}>
              <button 
                className="btn btn-secondary" 
                onClick={() => setShowStartDialog(null)}
              >
                Cancel
              </button>
              <button 
                className="btn btn-primary" 
                style={{ backgroundColor: '#10633B', borderColor: '#10633B' }}
                onClick={() => handleAction(showStartDialog, 'start')}
              >
                Start Session
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

