"use client";
import { apiClient } from '@/lib/apiClient';


import React, { useState, useEffect, useCallback } from 'react';
import Link from 'next/link';
import { PlusCircle, Search, Eye, Edit, Trash2, ChevronLeft, ChevronRight, BookOpen } from 'lucide-react';
import styles from './subjects.module.css';

export default function SubjectsPage() {
  const [subjects, setSubjects] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalItems, setTotalItems] = useState(0);

  // Filters
  const [search, setSearch] = useState('');
  const [departmentId, setDepartmentId] = useState('');
  const [programId, setProgramId] = useState('');
  const [semester, setSemester] = useState('');

  // Dropdown options (mocked endpoints for now)
  const [departments, setDepartments] = useState<any[]>([]);
  const [programs, setPrograms] = useState<any[]>([]);

  const fetchSubjects = useCallback(async () => {
    setLoading(true);
    try {
      const query = new URLSearchParams({
        page: page.toString(),
        limit: '10',
        ...(search && { search }),
        ...(departmentId && { departmentId }),
        ...(programId && { programId }),
        ...(semester && { semester }),
      });

      const res = await apiClient.get(`/api/faculty/subjects?${query.toString()}`, {
        credentials: 'include'
      });
      if (res.ok) {
        const json = await res.json();
        setSubjects(json.data?.subjects || []);
        setTotalPages(json.data?.pagination?.totalPages || 1);
        setTotalItems(json.data?.pagination?.total || 0);
      }
    } catch (error) {
      console.error("Failed to fetch subjects:", error);
    } finally {
      setLoading(false);
    }
  }, [page, search, departmentId, programId, semester]);

  const fetchFilters = async () => {
    try {
      // These endpoints do not exist currently, but we follow the instruction to use API data only.
      const deptRes = await apiClient.get('/api/departments').catch(() => null);
      if (deptRes && deptRes.ok) {
        const json = await deptRes.json();
        setDepartments(json.data || []);
      }
      const progRes = await apiClient.get('/api/programs').catch(() => null);
      if (progRes && progRes.ok) {
        const json = await progRes.json();
        setPrograms(json.data || []);
      }
    } catch (e) {
      console.error("Filter fetch failed", e);
    }
  };

  useEffect(() => {
    fetchFilters();
  }, []);

  useEffect(() => {
    fetchSubjects();
  }, [page, search, departmentId, programId, semester]);

  const handleDelete = async (id: string) => {
    if (confirm('Are you sure you want to delete this subject?')) {
      try {
        const res = await apiClient.get(`/api/faculty/subjects/${id}`, {
          method: 'DELETE',
          credentials: 'include'
        });
        if (res.ok) {
          fetchSubjects();
        } else {
          alert('Failed to delete subject.');
        }
      } catch (error) {
        console.error("Delete error", error);
      }
    }
  };

  const resetFilters = () => {
    setSearch('');
    setDepartmentId('');
    setProgramId('');
    setSemester('');
    setPage(1);
  };

  return (
    <div className="dashboard-scroll">
      {/* Page Header */}
      <div className="page-header">
        <div className="page-title-section">

